head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gCheckTF = true;
scwin.dataNum;
scwin.gMsgStr;
scwin.gType;
scwin.nmListSeq;
scwin.strCBData;
scwin.gSndloc = js_sndloc; // 송신처구분코드
scwin.gEmpNo = js_emp_no;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        tbox_nmlist_seq.hide();

        /*if(gLdMktTp == "1" || gLdMktTp == "2"){
        	showObj(rdo_MktTpCd, false);
        	showObj(label_29, false);
        }*/
        rdo_MktTpCd.hide();
        label_29.hide();
        lbl_9.hide();
        rdo_SndLocTpCd.hide();
        rdo_MktTpCd.setValue('9');
        scwin.gType = $c.frame.path("../").scwin.gType;
        if (scwin.gSndloc === "11" || scwin.gSndloc === "13") {
            if (scwin.gSndloc === "11") {
                rdo_SndLocTpCd.cols = "1";
                rdo_SndLocTpCd.format = "11^공시부";
                rdo_SndLocTpCd.reset();
            } else {
                rdo_SndLocTpCd.cols = "1";
                rdo_SndLocTpCd.format = "13^시장부";
                rdo_SndLocTpCd.reset();
            }
        } else {
            rdo_SndLocTpCd.cols = "2";
            rdo_SndLocTpCd.format = "11^공시부,13^시장부";
        }

        // 수정
        if (scwin.gType !== "N") {
            scwin.nmListSeq = $c.frame.path("../").inputSeq;
            await scwin.read();
        }
        // 신규
        else {
            const sbmOptions = {
                id : "sbm_dts_nmListInfo",
                action : "/gauceSystemierAdaptor.do",
                ref : "",
                target : "dts_nmListInfo=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            dts_nmListInfo.insertRow();
            if (scwin.gSndloc === "11" || scwin.gSndloc === "13") {
                rdo_SndLocTpCd.setValue(scwin.gSndloc);
            } else {
                rdo_SndLocTpCd.setValue("11");
            }
            rdo_MktTpCd.setValue('9');

            /*if(gLdMktTp == "1" || gLdMktTp == "2"){
            	showObj(rdo_MktTpCd, false);
            	showObj(label_29, false);
            	setObjectValue(rdo_MktTpCd, gLdMktTp);
            }
            else{
            	setObjectValue(rdo_MktTpCd, '9');
            }*/

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35005_POP.onpageload" });
    }
};

/**
         * @method
         * @name onpageunload
         * @description 화면 언로드 시 정리 처리
         * @returns {void}
         * @hidden N
         */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_checkList_OnLoadCompleted
 * @description dts_checkList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_checkList_OnLoadCompleted = function(rowcount) {

};

/**
 * @method
 * @name dts_checkList_OnLoadError
 * @description dts_checkList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_checkList_OnLoadError = async function() {
    try {
        await $c.win.alert("핸드폰 중복체크를 할수 없습니다. 시스템 관리자에게 문의하세요");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35005_POP.dts_checkList_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35005_POP.btn_save_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "비상연락망 " + scwin.gMsgStr));
        $c.frame.path("../").fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35005_POP.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "비상연락망 " + scwin.gMsgStr));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35005_POP.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name dts_checkList_OnLoadCompleted
 * @description dts_checkList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_checkList_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_checkList.errorMsg) {
            await $c.win.alert("조회시 오류가 발생하였습니다. 시스템관리자에게 문의하세요");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35005_POP.dts_checkList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35005_POP.img_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name read
 * @description 수정
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    const sbmOptions = {
        id : "sbm_dts_nmListInfo",
        action : "/AtsContactInfo.do",
        ref : "",
        target : "dts_nmListInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name checkList
 * @description 번호중복체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkList = async function() {
    const sbmOptions = {
        id : "sbm_dts_checkList",
        action : "/AtsContactInfo.do",
        ref : "",
        target : "dts_checkList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const vCntNo = dts_checkList.getCellData(1, "CNTNO");
    if (vCntNo > 0) {
        scwin.gCheckTF = false;
    } else {
        scwin.gCheckTF = true;
    }
};

/**
 * @method
 * @name save
 * @description 저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    await scwin.checkList();
    if (scwin.gCheckTF === false) {
        await $c.win.alert("동일한 휴대폰 번호가 존재합니다.");
        return;
    }
    if (!await scwin.checkMaxLength1(tbox_belng_hq, 40, "소속본부")) {
        tbox_belng_hq.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(tbox_depnm, 40, "담당부서")) {
        tbox_depnm.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(tbox_chrgteam, 40, "담당팀")) {
        tbox_chrgteam.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(tbox_jobtitle, 40, "직위")) {
        tbox_jobtitle.focus();
        return;
    }

    // 필수
    if (tbox_empnm.getValue() === "") {
        await $c.win.alert("담당자명을 확인하여 주십시요");
        tbox_empnm.focus();
        return;
    }
    if (!await scwin.checkMaxLength1(tbox_empnm, 40, "담당자명")) {
        tbox_empnm.focus();
        return;
    }
    if (tbox_telno.getValue() === "") {
        await $c.win.alert("전화번호를 확인하여 주십시요");
        tbox_telno.focus();
        return;
    }
    if (isNaN(scwin.replace(tbox_telno.getValue()))) {
        await $c.win.alert("전화번호를 숫자형식으로 값을 입력해주세요.(구분은 '-', '.' 만 사용)");
        tbox_telno.focus();
        return;
    }
    if (tbox_cellphone.getValue() === "") {
        await $c.win.alert("핸드폰번호를 확인하여 주십시요");
        tbox_cellphone.focus();
        return;
    }
    if (isNaN(scwin.replace(tbox_cellphone.getValue()))) {
        await $c.win.alert("핸드폰번호를 숫자형식으로 값을 입력해주세요.(구분은 '-', '.' 만 사용)");
        tbox_cellphone.focus();
        return;
    }
    if (tbox_cellphone.getValue() === "") {
        await $c.win.alert("핸드폰번호를 확인하여 주십시요");
        tbox_cellphone.focus();
        return;
    }
    if (tbox_email.getValue() === "") {
        await $c.win.alert("E-mail 를 확인하여 주십시요");
        tbox_email.focus();
        return;
    }
    if ("" !== tbox_email.getValue()) {
        const a = tbox_email.getValue().indexOf('@');
        if (a <= 0 || a === tbox_email.getValue().length - 1) {
            await $c.win.alert("Email은 [id@krx.co.kr] 등의 형태로 입력하셔야 합니다.");
            tbox_email.focus();
            return;
        }
    }
    if (!await scwin.checkMaxLength1(tbox_email, 100, "이메일")) {
        tbox_email.focus();
        return;
    }
    if (scwin.gType === "N") {
        scwin.gMsgStr = "신규등록";
    } else {
        scwin.gMsgStr = "수정";
    }
    const rtn = window.confirm('[' + scwin.gMsgStr + ']하시겠습니까?');
    if (rtn === 1) {
        dts_nmListInfo.setCellData(1, "CONTN_ID", scwin.gType);
        dts_nmListInfo.setCellData(1, "LST_ADJPRN_ID", scwin.gEmpNo);
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/AtsContactInfo.do",
            ref : "dts_nmListInfo",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkMaxLength1
 * @description check Max Length1 처리
 * @param {Object} obj 컴포넌트
 * @param {Number} size size
 * @param {String} lbl lbl
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkMaxLength1 = async function(obj, size, lbl) {
    const overLen = ($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        await $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name replace
 * @description replace 처리
 * @param {*} datastr datastr
 * @returns {void}
 * @hidden N
 */
scwin.replace = function(datastr) {
    datastr = datastr.replace(/[-.]/g, "");
    datastr = datastr.replace(/\s/g, "");
    return datastr;
};
